[
  {
    "statement": "Several actions can be taken to mitigate the impacts of roads on amphibian populations.",
    "citations": []
  },
  {
    "statement": "Closing roads during seasonal amphibian migration has been found to be an effective protective measure.",
    "citations": [
      "842"
    ]
  },
  {
    "statement": "Studies in Germany showed that large numbers of amphibians were protected from death during breeding migrations at road closure sites.",
    "citations": [
      "842"
    ]
  },
  {
    "statement": "Large numbers of amphibians were also protected from death during breeding migrations at road closure sites with assisted crossings and barrier fences.",
    "citations": [
      "842"
    ]
  },
  {
    "statement": "Installing barrier fencing along roads is an effective measure to protect amphibians.",
    "citations": []
  },
  {
    "statement": "Seven of eight studies in Germany, Canada and the USA found that barrier fencing with culverts decreased amphibian road deaths.",
    "citations": []
  },
  {
    "statement": "The effectiveness of barrier fencing is dependent on the fence length and material.",
    "citations": []
  },
  {
    "statement": "Barriers must be at least 0.6 m high to prevent some amphibian species from climbing over the barriers.",
    "citations": [
      "756"
    ]
  },
  {
    "statement": "Installing culverts or tunnels as road crossings for amphibians has shown significant success.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Six of seven studies in Canada, Germany, Italy, Hungary and the USA found that installing culverts or tunnels significantly decreased amphibian road deaths.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "The installation of culverts or tunnels was most effective when barrier fencing was also installed.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Fifteen of 24 studies found that culverts and tunnels were used by amphibians.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Amphibian usage rates of culverts and tunnels were found to be 15-85% of amphibians or involved 3-15 species.",
    "citations": [
      "884"
    ]
  },
  {
    "statement": "Restoring habitat connectivity can be an effective measure for protecting amphibians.",
    "citations": []
  },
  {
    "statement": "A study in Italy showed that raising a road on a viaduct to restore connectivity between two wetlands significantly decreased deaths of migrating amphibians.",
    "citations": [
      "840"
    ]
  },
  {
    "statement": "Warning signage for motorists has been tested but showed limited effectiveness in protecting amphibians.",
    "citations": []
  },
  {
    "statement": "One study in the UK found that despite warning signs and human assistance, over 500 toads were still killed on some roads.",
    "citations": [
      "841"
    ]
  }
]

[
  {
    "statement": "Based on studies in USA forests, different partial harvesting methods show varied impacts on salamander populations compared to clearcutting.",
    "citations": []
  },
  {
    "statement": "A meta-analysis of 24 studies in North America found that partial harvest methods resulted in smaller reductions in salamander populations than clearcutting.",
    "citations": [
      "844",
      "851",
      "852"
    ]
  },
  {
    "statement": "Partial harvest methods include harvesting groups or individual trees, thinning, and shelterwood harvesting.",
    "citations": [
      "844",
      "851",
      "852"
    ]
  },
  {
    "statement": "Three studies in the USA found that shelterwood harvesting resulted in higher, similar, or initially higher and then similar salamander abundance compared to clearcutting.",
    "citations": [
      "851"
    ]
  },
  {
    "statement": "Three studies found that harvesting trees in small groups did not result in higher amphibian or salamander abundance when compared to clearcutting.",
    "citations": [
      "844"
    ]
  },
  {
    "statement": "Two studies in the USA found that leaving a low density of trees during leave-tree harvesting did not result in higher salamander abundance compared to clearcutting.",
    "citations": [
      "846"
    ]
  },
  {
    "statement": "Four studies in the USA comparing amphibians in thinned to clearcut forests found either higher amphibian abundance, a less negative overall response, or mixed effects on abundance.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "The effects of thinning on amphibian abundance depended on species, life stage, and time since harvest.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "One study found that emigrating salamanders used thinned forest significantly more than clearcuts.",
    "citations": [
      "852"
    ]
  },
  {
    "statement": "When compared to unharvested areas, all partial harvesting methods showed negative impacts on salamanders.",
    "citations": [
      "844",
      "851",
      "846",
      "852"
    ]
  },
  {
    "statement": "Compared to unharvested areas, harvesting trees in small groups significantly decreased salamander abundance and changed species composition.",
    "citations": [
      "844"
    ]
  },
  {
    "statement": "In two of three studies, shelterwood harvesting decreased salamander abundance and changed species composition compared to unharvested areas.",
    "citations": [
      "851"
    ]
  },
  {
    "statement": "Compared to unharvested areas, leave-tree harvesting decreased salamander abundance and changed species composition.",
    "citations": [
      "846"
    ]
  },
  {
    "statement": "Thinning showed mixed effects on salamanders depending on the amphibian species and time since harvest when compared to unharvested areas.",
    "citations": [
      "852"
    ]
  }
]

[
  {
    "statement": "Controlling fish populations to protect amphibians shows several potential benefits and some documented harms.",
    "citations": []
  },
  {
    "statement": "Three studies found that eliminating fish using rotenone increased numbers of amphibian species, abundance and recruitment.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Three studies found that eliminating fish using rotenone increased newt populations.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "One review found that fish control, which included using rotenone, increased breeding success for four amphibian species.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Four studies found that removing fish by catching them significantly increased the abundance of salamanders or frogs.",
    "citations": [
      "827"
    ]
  },
  {
    "statement": "Four studies found that removing fish by catching them increased the recruitment, survival and population growth rate of the cascades frog.",
    "citations": [
      "827"
    ]
  },
  {
    "statement": "One controlled study found that excluding fish using a barrier increased weight gain of axolotls.",
    "citations": [
      "829"
    ]
  },
  {
    "statement": "Two replicated studies found when rotenone was applied, many frogs died.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "Two replicated studies found when rotenone was applied, a small number of newts showed symptoms of negative effects.",
    "citations": [
      "828"
    ]
  },
  {
    "statement": "One before-and-after study found that fish control had no significant effect on great crested newt populations.",
    "citations": [
      "827"
    ]
  },
  {
    "statement": "One before-and-after study found that fish remained or returned within a few years after control efforts.",
    "citations": [
      "827"
    ]
  },
  {
    "statement": "One replicated, before-and-after study found that fish control did not increase green toad breeding success.",
    "citations": [
      "827"
    ]
  },
  {
    "statement": "One replicated, before-and-after study found that fish were soon reintroduced after a control effort.",
    "citations": [
      "827"
    ]
  }
]

[
  {
    "statement": "Evidence from action documents shows multiple forms of public engagement in amphibian conservation with measurable outcomes in Europe and the USA.",
    "citations": []
  },
  {
    "statement": "Citizen science programs demonstrate substantial public participation in amphibian conservation.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Studies in Canada, the UK, and the USA found that amphibian data collection projects engaged between 100 and 10,506 volunteers.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Amphibian data collection projects were active in 16 to 17 states in the USA.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Volunteers in the UK and USA undertook 412 surveys for amphibian conservation.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Volunteers surveyed between 121 and 7,872 sites for amphibians in the UK and USA.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Volunteers swabbed almost 6,000 amphibians in studies across the UK and USA.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Volunteers submitted thousands of amphibian records across studies in the UK and USA.",
    "citations": [
      "760"
    ]
  },
  {
    "statement": "Habitat management involving volunteers shows conservation effectiveness.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Before-and-after studies in Estonia and Taiwan found that habitat management with volunteer participation increased natterjack toad and Taipei frog populations.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Studies in Estonia, the USA, and the UK found that between eight and 41,000 volunteers were engaged in aquatic and terrestrial habitat restoration programmes for amphibians.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Individual habitat restoration programmes for amphibians restored up to 1,023 ponds.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Individual habitat restoration programmes for amphibians restored over 11,500 square kilometers of habitat.",
    "citations": [
      "777"
    ]
  },
  {
    "statement": "Public awareness campaigns demonstrated public reach and some positive conservation outcomes.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "Studies in Estonia and the UK found that raising public awareness, along with other interventions, increased the numbers of natterjack toads.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "Raising public awareness, combined with other interventions, created 1,023 ponds for amphibians in Estonia and the UK.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "Awareness campaigns in Panama and the UK reached over 50,000 members of the public each year.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "Awareness campaigns in Panama and the UK trained 1,016 people at 57 events over four years.",
    "citations": [
      "831"
    ]
  },
  {
    "statement": "Education programmes show improvement in public knowledge and achieve conservation outcomes.",
    "citations": [
      "776"
    ]
  },
  {
    "statement": "Studies in Germany, Mexico, Zimbabwe, and the USA found that education programmes increased the amphibian knowledge of students, boatmen, and their tourists.",
    "citations": [
      "776"
    ]
  },
  {
    "statement": "A study in Taiwan found that education programmes about wetlands and amphibians, along with other interventions, doubled a population of Taipei frogs.",
    "citations": [
      "776"
    ]
  },
  {
    "statement": "Road assistance programs demonstrate substantial volunteer engagement despite having mixed conservation outcomes.",
    "citations": [
      "784"
    ]
  },
  {
    "statement": "Studies in Germany, the UK, and Italy found that large numbers of amphibians were moved across roads by patrols, ranging from 7,532 toads to half a million annually.",
    "citations": [
      "784"
    ]
  },
  {
    "statement": "In the UK, there were over 400 patrols to assist amphibians crossing roads.",
    "citations": [
      "784"
    ]
  },
  {
    "statement": "In the UK, 71 road patrols spent an average of 90 person-hours moving toads.",
    "citations": [
      "784"
    ]
  }
]

[
  {
    "statement": "According to global reviews of amphibian translocation efforts, 65% of amphibian translocations that could be assessed resulted in established breeding populations or substantial recruitment to the adult population.",
    "citations": [
      "854"
    ]
  },
  {
    "statement": "A review of release programs for captive-bred or head-started amphibians found that 41% of programs showed evidence of breeding in the wild for multiple generations.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "A review of release programs for captive-bred or head-started amphibians found that 29% of programs showed some evidence of breeding.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "A review of release programs for captive-bred or head-started amphibians found that 12% of programs showed evidence of survival following release.",
    "citations": [
      "871"
    ]
  },
  {
    "statement": "For head-started amphibians specifically, six of 10 studies found that released head-started tadpoles, metamorphs or juveniles established breeding populations.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "For head-started amphibians specifically, six of 10 studies found that released head-started tadpoles, metamorphs or juveniles increased frog or toad populations.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Two studies on head-started amphibians found mixed results, with breeding populations established in 12 of 17 studies reviewed.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Two studies on head-started amphibians found mixed results, with breeding populations established at two of four sites.",
    "citations": [
      "881"
    ]
  },
  {
    "statement": "Studies indicated that translocations of over 1,000 animals were more successful.",
    "citations": [
      "854"
    ]
  },
  {
    "statement": "The success of amphibian translocation was not related to whether animals came from wild or captive sources.",
    "citations": [
      "854"
    ]
  },
  {
    "statement": "The success of amphibian translocation was not related to the life-stage of the animals.",
    "citations": [
      "854"
    ]
  },
  {
    "statement": "The success of amphibian translocation was not related to the continent where the translocation occurred.",
    "citations": [
      "854"
    ]
  },
  {
    "statement": "The success of amphibian translocation was not related to the reason for the translocation.",
    "citations": [
      "854"
    ]
  }
]

[
  {
    "statement": "Several environmental management actions have been identified as alternatives to direct antifungal treatment for reducing chytridiomycosis threats to amphibians.",
    "citations": []
  },
  {
    "statement": "Adding salt to ponds has shown promise for reducing chytridiomycosis threats.",
    "citations": [
      "762"
    ]
  },
  {
    "statement": "One study in Australia found that a population of green and golden bell frogs remained free of chytridiomycosis for at least six months following salt addition to a pond containing the chytrid fungus.",
    "citations": [
      "762"
    ]
  },
  {
    "statement": "Removing the chytrid fungus from ponds through pond drying and fungicidal treatment has been tested.",
    "citations": [
      "766"
    ]
  },
  {
    "statement": "One study in Mallorca found that removing the chytrid fungus from ponds through pond drying and fungicidal treatment reduced infection levels but did not eradicate chytridiomycosis.",
    "citations": [
      "766"
    ]
  },
  {
    "statement": "Equipment sterilization when moving between amphibian sites is recommended to prevent disease spread.",
    "citations": [
      "768"
    ]
  },
  {
    "statement": "No direct evidence exists for the effectiveness of equipment sterilization on disease transmission between amphibian populations.",
    "citations": [
      "768"
    ]
  },
  {
    "statement": "Studies show that while Virkon S disinfectant does not affect amphibian survival, bleach significantly reduces the survival of tadpoles.",
    "citations": [
      "768"
    ]
  },
  {
    "statement": "The use of gloves when handling amphibians is practiced to prevent disease spread.",
    "citations": [
      "769"
    ]
  },
  {
    "statement": "Latex, vinyl, and nitrile gloves have been found to cause deaths in various tadpole species.",
    "citations": [
      "769"
    ]
  },
  {
    "statement": "Other proposed environmental approaches include using zooplankton to remove chytrid zoospores.",
    "citations": [
      "800"
    ]
  },
  {
    "statement": "Other proposed environmental approaches include preventing heavy usage or excluding wildfowl from aquatic habitat.",
    "citations": [
      "799"
    ]
  },
  {
    "statement": "No evidence exists yet for the effectiveness of using zooplankton to remove chytrid zoospores.",
    "citations": [
      "800"
    ]
  },
  {
    "statement": "No evidence exists yet for the effectiveness of preventing heavy usage or excluding wildfowl from aquatic habitat.",
    "citations": [
      "799"
    ]
  }
]

[
  {
    "statement": "Three studies in the USA found that understory removal using herbicide had no effect on amphibian abundance.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "Three studies in the USA found that understory removal using herbicide had some negative effects on amphibian abundance.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "A study in Canada found that following logging, American toad abundance was similar in stands with herbicide treatment and planting compared to stands left to regenerate naturally.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "A study in Canada found that following logging, wood frogs were lower in stands with herbicide treatment and planting compared to stands left to regenerate naturally.",
    "citations": [
      "778"
    ]
  },
  {
    "statement": "One study in the USA found that the number of amphibian species was significantly higher in plots with mechanical understory reduction compared to plots without mechanical understory reduction.",
    "citations": [
      "781"
    ]
  },
  {
    "statement": "One study in the USA found that amphibian abundance was not significantly higher in plots with mechanical understory reduction compared to plots without mechanical understory reduction.",
    "citations": [
      "781"
    ]
  },
  {
    "statement": "A study in the USA found that areas burned in combination with herbicide application had similar combined reptile and amphibian species richness and diversity compared to areas managed by burning alone, herbicide application alone, or left unmanaged.",
    "citations": [
      "3656"
    ]
  }
]

[
  {
    "statement": "The evidence suggests mixed effectiveness of legal and regulatory frameworks for amphibian conservation.",
    "citations": []
  },
  {
    "statement": "For species protection laws, three reviews in the Netherlands and UK found that legal protection of amphibian species was not effective at protecting populations during development.",
    "citations": [
      "779"
    ]
  },
  {
    "statement": "The number of great crested newt mitigation licences issued over 10 years increased to over 600 in England and Wales.",
    "citations": [
      "779"
    ]
  },
  {
    "statement": "One replicated site comparison study in the UK found that populations of natterjack toads were better protected at sites with a statutory level of habitat protection than at sites outside protected areas.",
    "citations": [
      "820"
    ]
  },
  {
    "statement": "A before-and-after study showed that a common frog population increased but common toads decreased following pond protection during development.",
    "citations": [
      "820"
    ]
  },
  {
    "statement": "For trade regulation, one review found that legislation to reduce trade in two frog species resulted in the recovery of over-exploited populations.",
    "citations": [
      "785",
      "824"
    ]
  },
  {
    "statement": "One study in South Africa found that the number of permits issued for scientific and educational use of amphibians increased from 1987 to 1990.",
    "citations": [
      "785"
    ]
  },
  {
    "statement": "Three studies in Denmark, Sweden and Taiwan found that payments to farmers created amphibian breeding habitat or increased frog or toad populations.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "A second study in Taiwan found that payments did not maintain green tree frog habitat.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "One replicated site comparison study in the Netherlands found that ditches managed under agri-environment schemes had higher numbers of amphibian species and higher abundance than ditches managed conventionally.",
    "citations": [
      "818"
    ]
  },
  {
    "statement": "Studies from the USA showed limited effectiveness for mitigation requirements.",
    "citations": [
      "3386"
    ]
  },
  {
    "statement": "Four studies reported that requiring mitigation of impacts to wetlands did not prevent loss of wetland area, as the total area restored or created was less than the area destroyed.",
    "citations": [
      "3386"
    ]
  },
  {
    "statement": "Eight studies reported compliance issues with mitigation requirements.",
    "citations": [
      "3386"
    ]
  },
  {
    "statement": "Five studies found that the total area of wetlands conserved was less than the area required in permits.",
    "citations": [
      "3386"
    ]
  }
]

[
  {
    "statement": "Livestock grazing on agricultural lands has mixed documented effects on amphibian habitats and populations.",
    "citations": []
  },
  {
    "statement": "Three replicated, site comparison studies in the USA showed that excluding livestock from streams or ponds did not increase the numbers of amphibian species or the overall abundance of amphibians.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "Two studies found that the abundance of green frogs and/or American toads was higher with livestock grazing.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "A randomized, replicated, controlled, before-and-after study in the USA found that excluding cattle from ponds did not increase the numbers of eggs of Columbia spotted frogs.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "A randomized, replicated, controlled, before-and-after study in the USA found that excluding cattle from ponds did not increase the larval survival of Columbia spotted frogs.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "Three replicated, site comparison studies in the USA found that excluding livestock from streams or ponds increased amphibian larval abundance.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "Three replicated, site comparison studies in the USA found that excluding livestock from streams or ponds increased the abundance of green frog metamorphs.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "A before-and-after study in the UK found that pond restoration that included livestock exclusion increased pond use by breeding natterjack toads.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "Livestock exclusion studies document impacts on wetland vegetation that may affect amphibian habitat quality.",
    "citations": [
      "2969",
      "2966"
    ]
  },
  {
    "statement": "Marshes and pools fenced to exclude cattle for periods ranging from 1 to 30 years showed increased vegetation abundance and height around pond margins.",
    "citations": [
      "2966"
    ]
  },
  {
    "statement": "Increased vegetation abundance and height around pond margins could provide improved amphibian habitat structure.",
    "citations": [
      "2966"
    ]
  },
  {
    "statement": "Excluding cattle allowed better growth of mangrove vegetation in brackish and saline swamps.",
    "citations": [
      "2969"
    ]
  },
  {
    "statement": "The effects of livestock grazing on amphibians are species-specific and context-dependent.",
    "citations": []
  },
  {
    "statement": "Some amphibian species benefit from grazing.",
    "citations": [
      "746"
    ]
  },
  {
    "statement": "Other amphibian species benefit from livestock exclusion.",
    "citations": [
      "746",
      "2969",
      "2966"
    ]
  }
]

[
  {
    "statement": "Several treatments are available for amphibians infected with chytridiomycosis.",
    "citations": []
  },
  {
    "statement": "Antifungal treatments show the most promise for treating amphibians with chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "Twelve of 16 studies found that antifungal treatment cured or increased the survival of amphibians with chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "Four studies found antifungal treatments did not cure chytridiomycosis but reduced infection levels.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "The antifungal Itraconazole was specifically effective against chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "Six of eight studies found Itraconazole cured amphibians of chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "One study found Itraconazole reduced infection levels of chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "One study showed mixed effects for Itraconazole as a treatment for chytridiomycosis.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "Six studies found that specific fungicides caused death or other negative side effects in amphibians.",
    "citations": [
      "882"
    ]
  },
  {
    "statement": "Temperature treatment is another effective option for treating amphibians with chytridiomycosis.",
    "citations": [
      "770"
    ]
  },
  {
    "statement": "Four of five studies found that increasing enclosure or water temperature to 30-37°C for over 16 hours cured frogs and toads of chytridiomycosis.",
    "citations": [
      "770"
    ]
  },
  {
    "statement": "One study found that heat treatment at 30-35°C for 36 hours did not cure northern leopard frogs of chytridiomycosis.",
    "citations": [
      "770"
    ]
  },
  {
    "statement": "Antibacterial treatments for chytridiomycosis have shown mixed results.",
    "citations": [
      "763"
    ]
  },
  {
    "statement": "Two studies found that treatment with chloramphenicol antibiotic ointment or solution cured green tree frogs and one Archey's frog of chytridiomycosis.",
    "citations": [
      "763"
    ]
  },
  {
    "statement": "One study found that the antibacterial trimethoprim-sulfadiazine increased survival time but did not cure blue-and-yellow poison dart frogs of chytridiomycosis.",
    "citations": [
      "763"
    ]
  },
  {
    "statement": "Antifungal skin bacteria or peptides show limited effectiveness against chytridiomycosis.",
